package in.gov.nic.apar.security;

import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { private final SecretKey key; public JwtService(@Value("${app.jwt-secret}") String secret){ if(secret.getBytes(StandardCharsets.UTF_8).length<32) throw new IllegalArgumentException("APP_JWT_SECRET must be at least 32 bytes"); key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)); } public String issue(String email,String role,long userId){ long now=System.currentTimeMillis(); return Jwts.builder().subject(email).claim("role",role).claim("uid",userId).issuedAt(new Date(now)).expiration(new Date(now+12*60*60*1000)).signWith(key).compact(); } public io.jsonwebtoken.Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
